import pandas as pd

def clean(df):
    df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    df['Category'] = df['Category'].str.strip()
    df['Category'] = df['Category'].apply(lambda x: x if x in allowed else pd.NA)
    return df

def answer(df):
    filtered = df[df['Category'].notna()]
    category_counts = filtered.groupby('Category').size().reset_index()
    category_counts.rename(columns={'size': 'count'}, inplace=True)
    result = {}
    for category, count in category_counts.itertuples():
        if count > 0:
            result[category] = count
    return result
